insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('51ae18f9-c62e-515b-b2b8-8a8733d5405a', '3b0a3555-284d-51eb-9c07-ca2eaf2c96b3', 'C', 'The children''s club meets late.', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('356fcb56-4c3f-568d-ab6c-d1a86597f7f5', '3b0a3555-284d-51eb-9c07-ca2eaf2c96b3', 'D', 'Computer classes are only at night.', false, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('d304e691-9a50-50c6-8b48-bae9aad07874', 'rmcm-0003', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "The city library has changed a lot in the last ten years. It still lends books, but it now also offers free computer classes, a quiet study room and a weekly club for children. Because more people visit in the evenings, it stays open until nine o''clock from Monday to Thursday.", "question": "Which services does the library offer now?"}'::jsonb, '{"correct": ["A", "D", "E"]}'::jsonb, 'The text lists computer classes, a study room and a children''s club. A café and bicycles are not mentioned.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
