insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e7ee6a7f-ab1a-536b-9a41-d8314c58caf7', 'd304e691-9a50-50c6-8b48-bae9aad07874', 'E', 'A quiet study room', true, 5);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('fb889ed0-fac4-5901-bff3-bb757ced9975', 'rop-0003', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Maria practised the recipe at home the next weekend."}, {"id": "p2", "text": "Maria wanted to learn to cook, so she joined an evening class."}, {"id": "p3", "text": "Her family liked it so much that she now cooks pasta every Sunday."}, {"id": "p4", "text": "At the first lesson, the teacher showed the group how to make fresh pasta."}]}'::jsonb, '{"order": ["p2", "p4", "p1", "p3"]}'::jsonb, 'The first sentence introduces Maria and her goal. Then come the first lesson, the practice at home and the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('08545cf3-95eb-59a0-b77d-438c4bffae0a', 'rwfib-0003', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "Many people {{1}} to shop online because it saves time. However, some still {{2}} visiting real shops at the weekend.", "blanks": {"1": ["preferring", "prefers", "prefer"], "2": ["enjoy", "enjoys", "enjoyed"]}}'::jsonb, '{"blanks": {"1": "prefer", "2": "enjoy"}}'::jsonb, 'After "Many people" (plural, present simple) we need "prefer". After "some still" in the present simple we need "enjoy".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('47820896-3ec8-515a-a3b2-f3490d899069', 'rfib-0003', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Drinking enough water helps your body {{1}} well. Doctors often {{2}} adults to drink several glasses a day.", "word_bank": ["advise", "work", "forget", "eat"]}'::jsonb, '{"blanks": {"1": "work", "2": "advise"}}'::jsonb, 'Your body "works" well; doctors "advise" people to do something. "eat" and "forget" do not fit the meaning.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('70780c39-91fb-5c30-ad95-96910f1685cd', 'rmcs-0004', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'beginner', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Scientists say that most adults need between seven and nine hours of sleep each night. People who sleep too little often find it hard to concentrate, and they may catch colds more easily. Using phones late at night can make it harder to fall asleep, because the bright screen tells the brain that it is still daytime.", "question": "According to the text, why can phones make it harder to fall asleep?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The text says the bright screen "tells the brain that it is still daytime".', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('ae959470-2c5c-5f53-9492-ac417f669167', '70780c39-91fb-5c30-ad95-96910f1685cd', 'A', 'They are too noisy.', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('a009653c-aa4b-5bc3-88b8-8887c0bd8383', '70780c39-91fb-5c30-ad95-96910f1685cd', 'B', 'They make people catch colds.', false, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('6cccaf66-d565-5ca8-a45b-adf2d14ce3f5', '70780c39-91fb-5c30-ad95-96910f1685cd', 'C', 'People use them to set alarms.', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('e29528a0-87f5-5c6c-8ebc-1e6f014fbfd8', '70780c39-91fb-5c30-ad95-96910f1685cd', 'D', 'The bright screen makes the brain think it is day.', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3d25c815-43ae-5ce3-8f35-6baac556e146', 'rmcm-0004', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'beginner', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Scientists say that most adults need between seven and nine hours of sleep each night. People who sleep too little often find it hard to concentrate, and they may catch colds more easily. Using phones late at night can make it harder to fall asleep, because the bright screen tells the brain that it is still daytime.", "question": "What problems does the text link with too little sleep?"}'::jsonb, '{"correct": ["B", "D"]}'::jsonb, 'The text mentions concentration and colds. Weight and eyesight are not mentioned.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('dc6f00ef-e7ad-5700-97a4-6a85aa792019', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'A', 'Poor eyesight', false, 1);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('3792ad0a-9b7f-5d9a-aa36-59261e417faf', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'B', 'Catching colds more easily', true, 2);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('b3b367e7-e040-55f3-8521-f6b4d6bdbb50', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'C', 'Weight gain', false, 3);
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values ('abbd5900-709e-50c4-8a30-5e4c09a79ffd', '3d25c815-43ae-5ce3-8f35-6baac556e146', 'D', 'Difficulty concentrating', true, 4);
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('3f8b9a67-ba0b-55ad-8bb6-b547c9c46681', 'rop-0004', '5ac15d51-a221-51df-974a-eb625cc75827', 'beginner', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "Our town has a new bicycle scheme."}, {"id": "p2", "text": "After using it, they simply return it to any station."}, {"id": "p3", "text": "Since the scheme started, traffic in the centre has fallen noticeably."}, {"id": "p4", "text": "Anyone can borrow a bike from one of twenty stations in the centre."}]}'::jsonb, '{"order": ["p1", "p4", "p2", "p3"]}'::jsonb, 'Start with the topic (the scheme), then how to borrow, how to return, and finally the result.', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('7a5068f2-413b-59c7-9f04-30f840e37b81', 'rwfib-0004', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'beginner', 'Choose the word that fits each gap in the text.', '{"text": "The concert was {{1}} because the singer was ill. Fans who had bought tickets were {{2}} their money back.", "blanks": {"1": ["cancel", "cancelling", "cancelled"], "2": ["offering", "offer", "offered"]}}'::jsonb, '{"blanks": {"1": "cancelled", "2": "offered"}}'::jsonb, 'Both gaps need the passive: "was cancelled" and "were offered".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('57dc25b1-4523-54bb-92e2-025de10bc904', 'rfib-0004', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'beginner', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "Learning a new language takes {{1}}. It is better to study a little every day than to {{2}} for many hours once a week.", "word_bank": ["money", "patience", "hurry", "study"]}'::jsonb, '{"blanks": {"1": "patience", "2": "study"}}'::jsonb, 'Learning a language "takes patience"; the sentence compares two ways to study. "hurry" and "money" do not fit.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('69bafee3-3f7a-5bfc-a674-7f889d9254d6', 'rmcs-0005', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Bees are important for growing food. When they move from flower to flower, they carry pollen, which plants need to make fruit and seeds. In many countries the number of bees has fallen, partly because of chemicals used on farms and partly because there are fewer wild flowers. Some cities now encourage people to plant flowers on balconies and in gardens to help.", "question": "What is the main idea of the text?"}'::jsonb, '{"correct": ["C"]}'::jsonb, 'The text explains why bees matter and why their numbers have fallen; the other answers are not stated.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
