insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('8dc4d170-9a58-5f01-b824-eac00fe4bb7e', 'rmcm-0018', 'eee3d137-7274-5c05-be6b-f8e051eb1853', 'intermediate', 'Read the text. Choose every answer that the text supports. There is more than one.', '{"passage": "Online courses allow people to study at their own speed and from any place with an internet connection. This makes them popular with adults who work full time. However, completion rates are often low. Learners who join a study group or set a regular weekly schedule are much more likely to finish their course.", "question": "Which statements about online courses are made in the text?"}'::jsonb, '{"correct": ["A", "C", "D"]}'::jsonb, 'Completion rates are "often low", so most learners do not finish.', 'Find several facts stated in a text.', array['Reading']::text[], '{}'::text[], 'published');
