insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('043936ab-737d-5a15-a575-f2c64de9e2ed', 'rop-0029', '5ac15d51-a221-51df-974a-eb625cc75827', 'advanced', 'The sentences are mixed up. Put them in an order that makes sense.', '{"paragraphs": [{"id": "p1", "text": "When a bee finds a good source of food, it returns to the hive and performs a series of movements."}, {"id": "p2", "text": "The honeybee dance is one of the most remarkable forms of animal communication."}, {"id": "p3", "text": "Using this information, the other bees can fly straight to the source."}, {"id": "p4", "text": "The direction and length of these movements tell other bees where the food is and how far away it lies."}]}'::jsonb, '{"order": ["p2", "p1", "p4", "p3"]}'::jsonb, 'Topic, the bee''s action, what "these movements" mean, and how others use "this information".', 'Use topic sentences, pronouns and linking words to order sentences.', array['Reorder']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('0de287a0-a005-5f7d-a141-0411563b0277', 'rwfib-0029', '2a8bdf6b-149a-5aa5-ba6f-351584a0c553', 'advanced', 'Choose the word that fits each gap in the text.', '{"text": "Rarely {{1}} a single discovery had such a wide impact. It has {{2}} changed the way doctors treat infections.", "blanks": {"1": ["having", "has", "have"], "2": ["fundamental", "fundamentally", "fundamentals"]}}'::jsonb, '{"blanks": {"1": "has", "2": "fundamentally"}}'::jsonb, 'After "Rarely" at the start we invert: "has a single discovery had". An adverb modifies "changed": "fundamentally".', 'Choose words that fit both grammar and meaning.', array['Reading', 'Writing']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('f3adff08-d500-5566-963c-c641575e4f2c', 'rfib-0029', '1176cf92-bbf8-5a0d-b2e8-3ae79d0fbf15', 'advanced', 'Some words are missing. Choose a word from the list for each gap. Some words are not needed.', '{"text": "The committee will {{1}} the applications and {{2}} successful candidates by the end of the month.", "word_bank": ["notify", "ignore", "punish", "review"]}'::jsonb, '{"blanks": {"1": "review", "2": "notify"}}'::jsonb, 'A committee reviews applications and notifies candidates.', 'Use collocations and meaning to fill gaps.', array['Reading']::text[], '{}'::text[], 'published');
insert into public.questions (id, external_id, category_id, difficulty, instructions, content, answer, explanation, learning_objective, scoring_criteria, key_points, status) values ('58e8e912-9ff7-5ff4-8f21-1b387bbae7fb', 'rmcs-0030', '99d3e519-b9f4-5651-baa2-3cae0a8f7810', 'intermediate', 'Read the text. Choose the one answer that the text supports.', '{"passage": "Noise from traffic, aircraft and building work is a growing problem in cities. Long-term exposure to loud noise can disturb sleep and raise stress levels. Some cities are tackling the problem by using quieter road surfaces, planting trees along busy roads and limiting building work to daytime hours.", "question": "What is the text mainly about?"}'::jsonb, '{"correct": ["D"]}'::jsonb, 'The text describes noise, its effects and how cities respond.', 'Find the answer the text supports, not just matching words.', array['Reading']::text[], '{}'::text[], 'published');
